"""Hook registration decorators.

Decorators attach point, lane, and timeout metadata as function attributes.
They do not wrap the builder function — mirroring ``rasa.mantle.tools.decorator``.

Public ``on_*`` / ``modify_*`` callables are generated from
:data:`~rasa.mantle.hooks.points.HOOK_POINT_SPECS` so point names exist in one
place only.
"""

from __future__ import annotations

from typing import Awaitable, Callable, TypeVar

from rasa.mantle.hooks.constants import (
    HOOK_LANE_ATTR,
    HOOK_POINT_ATTR,
    HOOK_TIMEOUT_MS_ATTR,
)
from rasa.mantle.hooks.points import HOOK_POINT_SPECS
from rasa.mantle.hooks.types import MODIFY_LANE, OBSERVE_LANE, HookLane

HookFunction = Callable[..., Awaitable[object]]
HookFunctionT = TypeVar("HookFunctionT", bound=HookFunction)
HookDecoratorFactory = Callable[[], Callable[[HookFunctionT], HookFunctionT]]


def _is_hook_function(func: object) -> bool:
    return callable(func) and hasattr(func, HOOK_POINT_ATTR)


def _make_decorator(
    point: str,
    lane: HookLane,
    default_timeout_ms: int,
) -> HookDecoratorFactory:
    def hook_decorator(
        *, timeout_ms: int | None = None
    ) -> Callable[[HookFunctionT], HookFunctionT]:
        resolved_timeout_ms = default_timeout_ms if timeout_ms is None else timeout_ms

        def attach_hook_metadata(func: HookFunctionT) -> HookFunctionT:
            setattr(func, HOOK_POINT_ATTR, point)
            setattr(func, HOOK_LANE_ATTR, lane)
            setattr(func, HOOK_TIMEOUT_MS_ATTR, resolved_timeout_ms)
            return func

        return attach_hook_metadata

    hook_decorator.__doc__ = (
        f"Register an {lane} hook for the {point!r} insertion point. "
        f"Default timeout: {default_timeout_ms} ms."
    )
    return hook_decorator


def _build_public_decorators() -> dict[str, HookDecoratorFactory]:
    decorators_by_name: dict[str, HookDecoratorFactory] = {}
    for point_name, point_spec in HOOK_POINT_SPECS.items():
        decorators_by_name[point_spec.observe_decorator] = _make_decorator(
            point_name,
            OBSERVE_LANE,
            point_spec.default_timeout_observe,
        )
        if point_spec.modify_decorator is not None:
            decorators_by_name[point_spec.modify_decorator] = _make_decorator(
                point_name,
                MODIFY_LANE,
                point_spec.default_timeout_modify,
            )
    return decorators_by_name


public_decorators_by_name = _build_public_decorators()


def _public_decorator(decorator_name: str) -> HookDecoratorFactory:
    """Return one catalogue decorator for explicit module-level re-exports."""
    return public_decorators_by_name[decorator_name]


on_turn_started = _public_decorator("on_turn_started")
on_turn_finished = _public_decorator("on_turn_finished")
on_incoming_message = _public_decorator("on_incoming_message")
modify_incoming_message = _public_decorator("modify_incoming_message")
on_model_request = _public_decorator("on_model_request")
modify_model_request = _public_decorator("modify_model_request")
on_model_response = _public_decorator("on_model_response")
modify_model_response = _public_decorator("modify_model_response")
on_tool_call = _public_decorator("on_tool_call")
modify_tool_call = _public_decorator("modify_tool_call")
on_tool_result = _public_decorator("on_tool_result")
modify_tool_result = _public_decorator("modify_tool_result")
on_knowledge_query = _public_decorator("on_knowledge_query")
modify_knowledge_query = _public_decorator("modify_knowledge_query")
on_knowledge_results = _public_decorator("on_knowledge_results")
modify_knowledge_results = _public_decorator("modify_knowledge_results")
on_outgoing_text = _public_decorator("on_outgoing_text")
modify_outgoing_text = _public_decorator("modify_outgoing_text")

ALL_PUBLIC_DECORATORS = tuple(public_decorators_by_name.values())
